# Enable Detailed Crash Dumps Write-Host "Configuring detailed crash dumps..." -ForegroundColor Cyan # Set crash dump type to Complete (2) # 0 = None, 1 = Minidump, 2 = Complete dump, 3 = Kernel dump Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "CrashDumpEnabled" -Value 2 -Type DWord -Force -ErrorAction Stop # Enable auto-restart (set to 1 to restart after dump) Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "AutoReboot" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Overwrite existing dump file Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "Overwrite" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Keep dump file path as default %SystemRoot%\MEMORY.DMP Write-Host "Crash dumps configured to generate complete memory dumps." -ForegroundColor Green Write-Host "Dump file will be saved to %SystemRoot%\MEMORY.DMP" -ForegroundColor Gray